// Gearforge audio engine: one-shot SFX, spatial machine ambience and ambient music on one AVAudioEngine.
// Sounds are generated by tools/audio/generate.py into App/Resources/Sounds (bundled as the folder "Sounds").
//
//   engine.mainMixerNode (master; 0 when disabled)
//     ├─ sfxMixer      (sfx volume)       ← 8 pooled AVAudioPlayerNodes for one-shots
//     ├─ ambienceMixer (sfx volume × trim) ← one looping AVAudioPlayerNode per LoopKind
//     └─ musicMixer    (music volume × trim) ← one AVAudioPlayerNode, looping the current track
//
// Everything is main-actor bound and lazy: the engine is built on the first play/updateAmbience/startMusic call.
// A missing or unreadable file is logged once and then ignored. Audio problems never crash the game.
import Foundation
import AVFoundation

@MainActor
final class AudioManager {
    static let shared = AudioManager()

    // MARK: Public types

    /// One-shot sounds; raw value = file name (without .wav) in the Sounds folder.
    enum SFX: String, CaseIterable {
        case uiTap = "ui_tap", uiOpen = "ui_open", uiClose = "ui_close", uiError = "ui_error"
        case uiSuccess = "ui_success", uiCraftDone = "ui_craft_done"
        case buildPlace = "build_place", buildRemove = "build_remove", rotate = "rotate", paste = "paste"
        case mineHitOre = "mine_hit_ore", mineHitTree = "mine_hit_tree", mineDone = "mine_done", pickup = "pickup"
        case footstep1 = "footstep_1", footstep2 = "footstep_2", footstep3 = "footstep_3", footstep4 = "footstep_4"
        case rocketLaunch = "rocket_launch", alert = "alert"

        static let footsteps: [SFX] = [.footstep1, .footstep2, .footstep3, .footstep4]

        /// Per-sound mix trim on top of the loudness baked into the files.
        var gain: Float {
            switch self {
            case .footstep1, .footstep2, .footstep3, .footstep4: return 0.55
            case .mineHitOre, .mineHitTree: return 0.7
            case .uiTap: return 0.8
            default: return 1
            }
        }
    }

    /// Machine ambience loops; file = "loop_" + raw value.
    enum LoopKind: String, CaseIterable {
        case assembler, furnace, drill, belt, steamEngine = "steam_engine", boiler, inserter, lab, pumpjack

        var fileName: String { "loop_" + rawValue }

        /// Maximum volume of the loop (when the summed attenuation saturates at 1).
        var gain: Float {
            switch self {
            case .belt: return 0.35
            case .inserter: return 0.3
            case .furnace, .boiler: return 0.45
            case .steamEngine: return 0.4
            case .lab: return 0.35
            default: return 0.4
            }
        }
    }

    // MARK: Tunables

    private let voiceCount = 8
    private let minRepeatInterval: TimeInterval = 0.06
    private let ambienceTrim: Float = 0.8
    private let musicTrim: Float = 0.6
    /// Distance falloff: 1 / (1 + d² / falloff²), in tiles.
    private let falloffSq = 36.0
    private let panRange = 10.0          // tiles of x offset for a full (±0.8) pan
    private let rampTimeConstant = 0.09  // s; ~92 % of a change is reached after 0.25 s
    private let musicFade: Double = 3.0
    private let musicGap: ClosedRange<Double> = 20...60
    private let musicPasses = 2          // times each track (a seamless loop) repeats before fading out

    // MARK: State

    private final class Voice {
        let node = AVAudioPlayerNode()
        var busyUntil: TimeInterval = 0
    }

    private final class LoopVoice {
        let node = AVAudioPlayerNode()
        let buffer: AVAudioPCMBuffer
        var current: Float = 0
        var target: Float = 0
        var pan: Float = 0
        var targetPan: Float = 0
        var scheduled = false
        var playing = false
        init(buffer: AVAudioPCMBuffer) { self.buffer = buffer }
    }

    private let engine = AVAudioEngine()
    private let sfxMixer = AVAudioMixerNode()
    private let ambienceMixer = AVAudioMixerNode()
    private let musicMixer = AVAudioMixerNode()
    private let musicNode = AVAudioPlayerNode()

    private var isSetUp = false
    private var voices: [Voice] = []
    private var voiceFormat: AVAudioFormat?
    private var buffers: [SFX: AVAudioPCMBuffer] = [:]
    private var lastPlayed: [SFX: TimeInterval] = [:]
    private var loops: [LoopKind: LoopVoice] = [:]
    private var musicTracks: [AVAudioPCMBuffer] = []
    private var musicFormat: AVAudioFormat?
    private var musicTrackIndex = Int.random(in: 0..<16)
    private var currentMusic: AVAudioPCMBuffer?
    private var musicLevel: Float = 0

    private var masterVolume: Float = 1
    private var musicVolume: Float = 0.6
    private var sfxVolume: Float = 1
    private var enabled = true
    private var paused = false
    private var interrupted = false
    private var musicWanted = false
    /// The engine was (or may have been) stopped behind our back: player nodes must be re-scheduled on resume.
    private var needsRearm = false

    private var rampTask: Task<Void, Never>?
    private var musicTask: Task<Void, Never>?
    private var observers: [NSObjectProtocol] = []
    private var logged: Set<String> = []

    private init() {}

    // MARK: Public API

    /// Volumes 0…1. `enabled == false` silences everything and pauses the engine.
    func configure(master: Double, music: Double, sfx: Double, enabled: Bool) {
        masterVolume = Float(min(max(master, 0), 1))
        musicVolume = Float(min(max(music, 0), 1))
        sfxVolume = Float(min(max(sfx, 0), 1))
        let wasEnabled = self.enabled
        self.enabled = enabled
        guard isSetUp else { return }
        applyVolumes()
        if !enabled && wasEnabled {
            silenceLoopsImmediately()
            if engine.isRunning { engine.pause() }
        } else if enabled && !wasEnabled && musicWanted {
            resume()
        }
    }

    /// Plays a one-shot. `volume` 0…1, `pan` -1 (left)…1 (right). The same sound is rate-limited to every 60 ms.
    func play(_ sfx: SFX, volume: Float = 1, pan: Float = 0) {
        guard canSound else { return }
        setUpIfNeeded()
        guard let buffer = buffers[sfx] else { logOnce("missing:\(sfx.rawValue)", "sound \(sfx.rawValue).wav unavailable"); return }
        let now = ProcessInfo.processInfo.systemUptime
        if let last = lastPlayed[sfx], now - last < minRepeatInterval { return }
        lastPlayed[sfx] = now
        guard !voices.isEmpty, ensureRunning() else { return }
        guard let voice = voices.first(where: { $0.busyUntil <= now }) ?? voices.min(by: { $0.busyUntil < $1.busyUntil })
        else { return }
        if voice.busyUntil > now { voice.node.stop() }
        voice.node.volume = min(max(volume * sfx.gain, 0), 1)
        voice.node.pan = min(max(pan, -1), 1)
        voice.node.scheduleBuffer(buffer, at: nil, options: [], completionHandler: nil)
        if !voice.node.isPlaying { voice.node.play() }
        voice.busyUntil = now + duration(of: buffer)
    }

    /// Called ~4×/s by the renderer with the working machines in view (tile coordinates). Each LoopKind
    /// gets one looping voice with volume = clamp(Σ 1/(1+d²/36)) × gain, panned toward its loudest source.
    /// Kinds without sources fade out and pause.
    func updateAmbience(listener: (x: Double, y: Double), sources: [(kind: LoopKind, x: Double, y: Double)]) {
        guard canSound else {
            if isSetUp { for v in loops.values { v.target = 0 } }
            return
        }
        if sources.isEmpty && !isSetUp { return }
        setUpIfNeeded()
        var sum: [LoopKind: Double] = [:]
        var best: [LoopKind: (w: Double, dx: Double)] = [:]
        for s in sources {
            let dx = s.x - listener.x, dy = s.y - listener.y
            let w = 1.0 / (1.0 + (dx * dx + dy * dy) / falloffSq)
            sum[s.kind, default: 0] += w
            if w > (best[s.kind]?.w ?? -1) { best[s.kind] = (w, dx) }
        }
        var anyActive = false
        for (kind, voice) in loops {
            let level = min(sum[kind] ?? 0, 1)
            voice.target = Float(level) * kind.gain
            if let b = best[kind] { voice.targetPan = Float(min(max(b.dx / panRange, -1), 1) * 0.8) }
            if voice.target > 0 || voice.current > 0 { anyActive = true }
        }
        if anyActive { startRamp() }
    }

    /// Starts the music cycle: a track fades in over 3 s, loops `musicPasses` times, fades out, then
    /// 20–60 s of silence before the next track.
    func startMusic() {
        musicWanted = true
        guard musicTask == nil else { return }
        musicTask = Task { @MainActor [weak self] in
            await self?.runMusic()
        }
    }

    func stopMusic() {
        musicWanted = false
        musicTask?.cancel()
        musicTask = nil
        guard isSetUp, currentMusic != nil else { return }
        // Short fade-out in its own task (the cycle task is cancelled).
        Task { @MainActor [weak self] in
            guard let self else { return }
            await self.fadeMusic(to: 0, over: 1.0)
            if !self.musicWanted { self.musicNode.stop(); self.currentMusic = nil }
        }
    }

    /// App went to background (true) / came back (false).
    func setPaused(_ p: Bool) {
        guard p != paused else { return }
        paused = p
        guard isSetUp else { return }
        if p {
            rampTask?.cancel(); rampTask = nil
            if engine.isRunning { engine.pause() }
        } else {
            // An interruption's "ended" notification is not guaranteed; becoming active again ends it. iOS may also
            // have stopped the engine while we were in the background, so always re-arm the players.
            interrupted = false
            needsRearm = true
            resume()
        }
    }

    // MARK: Setup

    private var canSound: Bool { enabled && !paused && !interrupted }

    private func setUpIfNeeded() {
        guard !isSetUp else { return }
        isSetUp = true
        configureSession()

        for mixer in [sfxMixer, ambienceMixer, musicMixer] {
            engine.attach(mixer)
            engine.connect(mixer, to: engine.mainMixerNode, format: nil)
        }

        for sfx in SFX.allCases {
            if let b = loadBuffer(sfx.rawValue) { buffers[sfx] = b }
        }
        voiceFormat = buffers[.uiTap]?.format ?? buffers.values.first?.format
        if let format = voiceFormat {
            // All one-shots share one format (44.1 kHz mono); a file that differs is dropped, not resampled.
            for (sfx, b) in buffers where !sameFormat(b.format, format) {
                buffers[sfx] = nil
                logOnce("format:\(sfx.rawValue)", "sound \(sfx.rawValue).wav has an unexpected format; skipped")
            }
            for _ in 0..<voiceCount {
                let v = Voice()
                engine.attach(v.node)
                engine.connect(v.node, to: sfxMixer, format: format)
                voices.append(v)
            }
        }

        for kind in LoopKind.allCases {
            guard let b = loadBuffer(kind.fileName) else { continue }
            let v = LoopVoice(buffer: b)
            engine.attach(v.node)
            engine.connect(v.node, to: ambienceMixer, format: b.format)
            v.node.volume = 0
            loops[kind] = v
        }

        var n = 1
        while let b = loadBuffer("music_\(n)", logMissing: n == 1) {
            if let f = musicFormat, !sameFormat(f, b.format) {
                logOnce("format:music_\(n)", "music_\(n).wav has a different format than music_1; skipped")
            } else {
                musicFormat = b.format
                musicTracks.append(b)
            }
            n += 1
        }
        if let f = musicFormat {
            engine.attach(musicNode)
            engine.connect(musicNode, to: musicMixer, format: f)
            musicNode.volume = 0
        }

        applyVolumes()
        engine.prepare()
        installObservers()
    }

    private func configureSession() {
        #if os(iOS) || GEARFORGE_TYPECHECK
        let session = AVAudioSession.sharedInstance()
        do {
            // .ambient: mixes with other apps' audio and obeys the ring/silent switch.
            try session.setCategory(.ambient, mode: .default, options: [])
            try session.setActive(true)
        } catch {
            logOnce("session", "AVAudioSession setup failed: \(error)")
        }
        #endif
    }

    private func installObservers() {
        let nc = NotificationCenter.default
        #if os(iOS) || GEARFORGE_TYPECHECK
        observers.append(nc.addObserver(forName: AVAudioSession.interruptionNotification, object: nil, queue: .main) { [weak self] note in
            let typeRaw = note.userInfo?[AVAudioSessionInterruptionTypeKey] as? UInt
            let began = typeRaw.flatMap { AVAudioSession.InterruptionType(rawValue: $0) } == .began
            MainActor.assumeIsolated { self?.handleInterruption(began: began) }
        })
        observers.append(nc.addObserver(forName: AVAudioSession.mediaServicesWereResetNotification, object: nil, queue: .main) { [weak self] _ in
            MainActor.assumeIsolated { self?.handleEngineReset() }
        })
        #endif
        observers.append(nc.addObserver(forName: .AVAudioEngineConfigurationChange, object: engine, queue: .main) { [weak self] _ in
            MainActor.assumeIsolated { self?.handleEngineReset() }
        })
    }

    private func loadBuffer(_ name: String, logMissing: Bool = true) -> AVAudioPCMBuffer? {
        guard let url = Bundle.main.url(forResource: name, withExtension: "wav", subdirectory: "Sounds")
                ?? Bundle.main.url(forResource: name, withExtension: "wav") else {
            if logMissing { logOnce("missing:\(name)", "sound \(name).wav not found in bundle") }
            return nil
        }
        do {
            let file = try AVAudioFile(forReading: url)
            let frames = AVAudioFrameCount(max(0, file.length))
            guard frames > 0, let buffer = AVAudioPCMBuffer(pcmFormat: file.processingFormat, frameCapacity: frames) else {
                logOnce("empty:\(name)", "sound \(name).wav is empty")
                return nil
            }
            try file.read(into: buffer)
            return buffer
        } catch {
            logOnce("read:\(name)", "sound \(name).wav unreadable: \(error)")
            return nil
        }
    }

    // MARK: Engine helpers

    private func applyVolumes() {
        engine.mainMixerNode.outputVolume = enabled ? masterVolume : 0
        sfxMixer.outputVolume = sfxVolume
        ambienceMixer.outputVolume = sfxVolume * ambienceTrim
        musicMixer.outputVolume = musicVolume * musicTrim
    }

    /// Starts the engine if needed; false if it cannot run (then the caller skips the sound).
    private func ensureRunning() -> Bool {
        guard canSound else { return false }
        if engine.isRunning { return true }
        do {
            try engine.start()
            return true
        } catch {
            logOnce("start", "AVAudioEngine failed to start: \(error)")
            return false
        }
    }

    /// After a stop/reset of the engine, player nodes have lost their schedules: re-arm loops and music.
    private func resumeAfterEngineRestart() {
        for v in voices { v.node.stop(); v.busyUntil = 0 }
        for v in loops.values {
            v.node.stop()
            v.scheduled = false
            v.playing = false
        }
        if let track = currentMusic, musicFormat != nil {
            musicNode.stop()
            musicNode.scheduleBuffer(track, at: nil, options: [.loops], completionHandler: nil)
            musicNode.volume = musicLevel
            if engine.isRunning { musicNode.play() }
        }
        startRamp()
    }

    private func handleInterruption(began: Bool) {
        needsRearm = true
        if began {
            interrupted = true
            rampTask?.cancel(); rampTask = nil
        } else {
            interrupted = false
            resume()
        }
    }

    private func handleEngineReset() {
        needsRearm = true
        resume()
    }

    /// Restarts output after a pause / interruption / reset / re-enable. Every `play()` on a player node is
    /// guarded by a running engine (AVAudioPlayerNode raises an exception otherwise).
    private func resume() {
        guard isSetUp, canSound else { return }
        #if os(iOS) || GEARFORGE_TYPECHECK
        try? AVAudioSession.sharedInstance().setActive(true)
        #endif
        guard ensureRunning() else { return }
        if needsRearm {
            needsRearm = false
            resumeAfterEngineRestart()
        } else {
            startRamp()
        }
    }

    // MARK: Ambience ramp

    private func startRamp() {
        guard rampTask == nil, canSound else { return }
        rampTask = Task { @MainActor [weak self] in
            var last = ProcessInfo.processInfo.systemUptime
            while !Task.isCancelled {
                try? await Task.sleep(nanoseconds: 16_000_000)
                guard let self, !Task.isCancelled else { return }
                let now = ProcessInfo.processInfo.systemUptime
                let settled = self.rampStep(dt: min(now - last, 0.1))
                last = now
                if settled { self.rampTask = nil; return }
            }
        }
    }

    /// One smoothing step for all loop voices; returns true when nothing is moving any more.
    private func rampStep(dt: Double) -> Bool {
        let k = Float(1 - exp(-dt / rampTimeConstant))
        var settled = true
        for v in loops.values {
            if v.target > 0 && !v.playing {
                guard ensureRunning() else { return true }
                if !v.scheduled {
                    v.node.scheduleBuffer(v.buffer, at: nil, options: [.loops], completionHandler: nil)
                    v.scheduled = true
                }
                v.pan = v.targetPan
                v.node.pan = v.pan
                v.node.play()
                v.playing = true
            }
            let diff = v.target - v.current
            if abs(diff) < 0.002 {
                v.current = v.target
            } else {
                v.current += diff * k
                settled = false
            }
            let pd = v.targetPan - v.pan
            if abs(pd) > 0.005 { v.pan += pd * k; settled = false } else { v.pan = v.targetPan }
            v.node.volume = v.current
            v.node.pan = v.pan
            if v.target == 0 && v.current == 0 && v.playing {
                v.node.pause()
                v.playing = false
            }
        }
        return settled
    }

    private func silenceLoopsImmediately() {
        rampTask?.cancel(); rampTask = nil
        for v in loops.values {
            v.target = 0; v.current = 0
            v.node.volume = 0
            if v.playing { v.node.pause(); v.playing = false }
        }
    }

    // MARK: Music

    private func runMusic() async {
        setUpIfNeeded()
        guard !musicTracks.isEmpty else { musicTask = nil; return }
        if !(await sleep(seconds: 2)) { return }
        while musicWanted && !Task.isCancelled {
            if !canSound {
                if !(await sleep(seconds: 1)) { return }
                continue
            }
            let track = musicTracks[musicTrackIndex % musicTracks.count]
            musicTrackIndex += 1
            guard ensureRunning() else {
                if !(await sleep(seconds: 5)) { return }
                continue
            }
            musicNode.stop()
            musicLevel = 0
            musicNode.volume = 0
            currentMusic = track
            musicNode.scheduleBuffer(track, at: nil, options: [.loops], completionHandler: nil)
            musicNode.play()
            await fadeMusic(to: 1, over: musicFade)
            let hold = duration(of: track) * Double(musicPasses) - 2 * musicFade
            if !(await sleep(seconds: max(hold, 5))) { return }
            await fadeMusic(to: 0, over: musicFade)
            if Task.isCancelled { return }
            musicNode.stop()
            currentMusic = nil
            if !(await sleep(seconds: Double.random(in: musicGap))) { return }
        }
    }

    private func fadeMusic(to target: Float, over seconds: Double) async {
        let start = musicLevel
        let steps = max(1, Int(seconds / 0.05))
        for i in 1...steps {
            if !(await sleep(seconds: seconds / Double(steps))) { return }
            let x = Float(i) / Float(steps)
            let s = x * x * (3 - 2 * x)
            musicLevel = start + (target - start) * s
            musicNode.volume = musicLevel
        }
    }

    /// Task-cancellation-aware sleep; false when cancelled.
    private func sleep(seconds: Double) async -> Bool {
        do {
            try await Task.sleep(nanoseconds: UInt64(max(0, seconds) * 1_000_000_000))
            return !Task.isCancelled
        } catch {
            return false
        }
    }

    // MARK: Utilities

    private func duration(of buffer: AVAudioPCMBuffer) -> Double {
        let rate = buffer.format.sampleRate
        return rate > 0 ? Double(buffer.frameLength) / rate : 0
    }

    private func sameFormat(_ a: AVAudioFormat, _ b: AVAudioFormat) -> Bool {
        a.sampleRate == b.sampleRate && a.channelCount == b.channelCount
    }

    private func logOnce(_ key: String, _ message: String) {
        guard !logged.contains(key) else { return }
        logged.insert(key)
        print("[Audio] \(message)")
    }
}
